            out.append("compatible" if (ov is None or (nv is not None and nv < ov)) else "breaking")
        elif key in upper:
            out.append("compatible" if (ov is None or (nv is not None and nv > ov)) else "breaking")
        else:
            # pattern / format / multipleOf / uniqueItems：新增或改变约束 = 收窄，
            # 移除约束 = 放宽。
            out.append("compatible" if nv is None else "breaking")
    return out

