def classify_pair(old: dict, new: dict) -> str:
    """比较同一路径字段的新旧生效定义，返回 ``compatible`` / ``breaking`` /
    ``metadata``。

    约定：
      * 新增非必填属性、放宽枚举、integer→number、增加默认值 → compatible；
      * 删除属性、新增必填、收窄类型/枚举、允许原本不接受的 null → breaking；
      * 仅标题/描述/注释变化 → metadata；
      * 其余收紧为 breaking，放宽为 compatible，同时有收有放按 breaking。
    """
    old_a = {k: old.get(k) for k in ANNOTATION_KEYS if k in old}
    new_a = {k: new.get(k) for k in ANNOTATION_KEYS if k in new}

    # 结构骨架（除注解外所有参与判定的键）。
    def structural(s: dict) -> dict:
        d = dict(s)
        for k in ANNOTATION_KEYS:
            d.pop(k, None)
        return d

    if _canonical(structural(old)) == _canonical(structural(new)):
        return "metadata" if old_a != new_a else "metadata"

    verdicts: list[str] = []

    # 1) 类型：integer -> number 放宽；出现新增的 null 为破坏性；其余集合变化收紧/扩展。
    ot, nt = _types(old), _types(new)
    if nt != ot:
        if ot == frozenset({"integer"}) and nt == frozenset({"number"}):
            verdicts.append("compatible")
        else:
            added = nt - ot
            if "null" in added:
                verdicts.append("breaking")
            elif ot and nt and nt > ot:
                verdicts.append("compatible")
            elif not ot:
                # 旧未约束类型、新给出具体类型：视为收窄。
                verdicts.append("breaking")
            else:
                verdicts.append("breaking")

    # 2) 枚举/const：取值集合扩大为放宽，缩小为收窄。
    oe, ne = _enum(old), _enum(new)
    if oe != ne:
        if oe is None and ne is None:
            pass
        elif oe is not None and ne is not None:
            oset, nset = frozenset(oe), frozenset(ne)
            verdicts.append("compatible" if oset < nset else "breaking")
        elif ne is None:
            verdicts.append("compatible")  # 取消枚举 = 放宽
        else:
            verdicts.append("breaking")  # 新增强枚举 = 收窄

    # 3) 数值/长度等边界：逐项比较。
    ob, nb = _bounds(old), _bounds(new)
    if ob != nb:
        verdicts.extend(_classify_bounds(ob, nb))

    # 4) default：出现默认值属于兼容；移除/改变默认值视为元数据级兼容调整，
    #    但仅当其单独出现时；这里给出 compatible 不影响破坏判定。
    if "default" in new and "default" not in old:
        verdicts.append("compatible")
    elif old.get("default") != new.get("default") and "default" in old and "default" in new:
        verdicts.append("metadata")

    # 5) 其余结构键（未知/新增约束键）：出现即为新增约束 → breaking；
    #    消失为放宽 → compatible。
    known = set(STRUCTURAL_KEYS) | set(ANNOTATION_KEYS) | {"default"}
    extra_o = {k for k in old if k not in known and not k.startswith("$") and k != "properties"}
    extra_n = {k for k in new if k not in known and not k.startswith("$") and k != "properties"}
    if extra_n - extra_o:
        verdicts.append("breaking")
    if extra_o - extra_n:
        verdicts.append("compatible")

    if "breaking" in verdicts:
        return "breaking"
    if "compatible" in verdicts:
        return "compatible"
    return "metadata"


def _classify_bounds(ob: dict, nb: dict) -> list[str]:
    """对数值边界做放宽/收窄判定。

    lower 类关键字（minimum 等）减小为放宽；upper 类增大为放宽；
    pattern/format/multipleOf/uniqueItems 出现或收紧为 breaking。
    """
    out: list[str] = []
    lower = ("minimum", "exclusiveMinimum", "minLength", "minItems", "minProperties")
    upper = ("maximum", "exclusiveMaximum", "maxLength", "maxItems", "maxProperties")

    for key in set(ob) | set(nb):
        ov, nv = ob.get(key), nb.get(key)
        if ov == nv:
            continue
        if key in lower:
            out.append("compatible" if (ov is None or (nv is not None and nv < ov)) else "breaking")
        elif key in upper:
            out.append("compatible" if (ov is None or (nv is not None and nv > ov)) else "breaking")
        else:
            # pattern / format / multipleOf / uniqueItems：新增或改变约束 = 收窄，
            # 移除约束 = 放宽。
            out.append("compatible" if nv is None else "breaking")
    return out

