    if "compatible" in verdicts:
        return "compatible"
    return "metadata"


def _classify_bounds(ob: dict, nb: dict) -> list[str]:
    """对数值边界做放宽/收窄判定。

    lower 类关键字（minimum 等）减小为放宽；upper 类增大为放宽；
    pattern/format/multipleOf/uniqueItems 出现或收紧为 breaking。
    """
    out: list[str] = []
    lower = ("minimum", "exclusiveMinimum", "minLength", "minItems", "minProperties")
    upper = ("maximum", "exclusiveMaximum", "maxLength", "maxItems", "maxProperties")

    for key in set(ob) | set(nb):
        ov, nv = ob.get(key), nb.get(key)
        if ov == nv:
            continue
        if key in lower:
            out.append("compatible" if (ov is None or (nv is not None and nv < ov)) else "breaking")
        elif key in upper:
            out.append("compatible" if (ov is None or (nv is not None and nv > ov)) else "breaking")
        else:
            # pattern / format / multipleOf / uniqueItems：新增或改变约束 = 收窄，
            # 移除约束 = 放宽。
            out.append("compatible" if nv is None else "breaking")
    return out

