"""字段级破坏性变更识别。

输入两个同一 Schema 标识下的 JSON Schema 文档（基线版本、候选版本）与显式
字段重命名映射，产出确定性的字段级变更报告。

变更种类（``change_kind``）：
  * ``added``            新增字段（非必填兼容 / 必填破坏）
  * ``deleted``          删除字段（破坏）
  * ``modified``         结构定义变化（按收窄/放宽判定）
  * ``required_added``   既有字段新增必填约束（破坏）
  * ``required_removed`` 既有字段解除必填约束（兼容）
  * ``rename``           显式声明的重命名（按一次计入；破坏）
  * ``metadata``         仅标题/描述/注释变化（元数据变更）

兼容结论（``compatibility``）：``breaking`` / ``compatible`` / ``metadata``。
"""

from __future__ import annotations

import copy
import hashlib
import json
from typing import Any

from . import limits, pointer as ptr, schema_fields as sf
from .errors import ImpactAnalysisTooLarge, SchemaComparisonInvalid
from .impact import analyze_field
from .registry import Registry

RENAMED = "rename"
ADDED = "added"
DELETED = "deleted"
MODIFIED = "modified"
REQUIRED_ADDED = "required_added"
REQUIRED_REMOVED = "required_removed"
METADATA = "metadata"

BREAKING = "breaking"
COMPATIBLE = "compatible"
METADATA_COMPAT = "metadata"


def _expand(document: Any) -> dict[str, sf.Field]:
    return sf.expand(document)


def _is_required(field: sf.Field | None) -> bool:
    """字段是否被其父对象的 required 列表覆盖（展开时已合并 allOf）。"""
    if field is None:
        return False
    parent_path = ptr.parent(field.path)
    # fields 表由调用方持有，这里通过 required_paths 反查；为简化，
    # 调用方直接传入 required 集合，见 _required_set。
    raise NotImplementedError


def _required_set(fields: dict[str, sf.Field]) -> set[str]:
    """收集文档内全部被标记为必填的字段路径。"""
    out: set[str] = set()
    for f in fields.values():
        out.update(f.required_paths)
    return out


def _summary(schema: dict) -> dict[str, Any]:
    # required 是父节点对子字段的约束，不放进字段自身摘要。
    return {k: v for k, v in sf.summary(schema).items() if k != "required"}


def validate_renames(
    renames: list[dict] | list[tuple[str, str]] | None,
    old_fields: dict[str, sf.Field],
    new_fields: dict[str, sf.Field],
) -> list[tuple[str, str]]:
    """校验并规范化重命名映射，失败时抛 :class:`SchemaComparisonInvalid`。"""
    if renames is None:
        return []
    if not isinstance(renames, list):
        raise SchemaComparisonInvalid(
            "重命名映射必须是 [{from, to}, ...] 列表",
            details={"reason": "renames_not_list"},
        )

    pairs: list[tuple[str, str]] = []
    for i, item in enumerate(renames):
        if isinstance(item, dict):
            src, dst = item.get("from"), item.get("to")
        elif isinstance(item, (tuple, list)) and len(item) == 2:
            src, dst = item[0], item[1]
        else:
            src = dst = None
        if not isinstance(src, str) or not isinstance(dst, str) or not src or not dst:
            raise SchemaComparisonInvalid(
                f"第 {i} 条重命名映射必须包含非空字符串 from 与 to",
                details={"reason": "rename_invalid", "index": i},
            )
        pairs.append((src, dst))

    # 1) 起点/终点必须存在于对应版本。
    for src, dst in pairs:
        if src not in old_fields:
            raise SchemaComparisonInvalid(
                f"重命名起点 {src} 在基线版本中不存在",
                details={"reason": "rename_from_not_found", "path": src},
            )
        if dst not in new_fields:
            raise SchemaComparisonInvalid(
                f"重命名终点 {dst} 在候选版本中不存在",
                details={"reason": "rename_to_not_found", "path": dst},
            )

    # 2) 同一路径不得被重复映射：所有端点两两不重复，且起点≠终点。
    endpoints: list[str] = []
    for src, dst in pairs:
        endpoints.extend((src, dst))
    seen: set[str] = set()
    for ep in endpoints:
        if ep in seen:
            raise SchemaComparisonInvalid(
                f"路径 {ep} 在重命名映射中被重复使用",
                details={"reason": "rename_duplicate", "path": ep},
            )
        seen.add(ep)

    # 3) 任意两个端点的子树不得重叠，否则同一路径被隐式映射两次。
    ordered = sorted(seen, key=lambda p: (ptr.parse(p), p))
    for a, b in zip(ordered, ordered[1:]):
        if ptr.is_under(a, b):
            raise SchemaComparisonInvalid(
                f"重命名端点 {a} 与 {b} 的子树重叠，映射不明确",
                details={"reason": "rename_overlapping", "paths": [a, b]},
            )

    # 4) 跨版本一致性：起点不应仍在候选版本中、终点不应已在基线版本中，
    #    否则映射与两份文档实际呈现的路径不一致。
    for src, dst in pairs:
        if src in new_fields:
            raise SchemaComparisonInvalid(
                f"重命名起点 {src} 仍存在于候选版本，映射跨版本不一致",
                details={"reason": "rename_cross_version_inconsistent", "path": src},
            )
        if dst in old_fields:
            raise SchemaComparisonInvalid(
                f"重命名终点 {dst} 已存在于基线版本，映射跨版本不一致",
                details={"reason": "rename_cross_version_inconsistent", "path": dst},
            )

    return pairs


def _entry(
    change_kind: str,
    compatibility: str,
    old_path: str | None,
    new_path: str | None,
    old_schema: dict | None,
    new_schema: dict | None,
    impacts: dict | None = None,
) -> dict[str, Any]:
    return {
        "path": new_path if new_path is not None else old_path,
        "old_path": old_path,
        "new_path": new_path,
        "old_summary": _summary(old_schema) if old_schema is not None else None,
        "new_summary": _summary(new_schema) if new_schema is not None else None,
        "change_kind": change_kind,
        "compatibility": compatibility,
        "direct_assets": list(impacts["direct_assets"]) if impacts else [],
        "transitive_assets": list(impacts["transitive_assets"]) if impacts else [],
    }


def _compare_matched(
    old_field: sf.Field,
    new_field: sf.Field,
    old_required: bool,
    new_required: bool,
) -> dict[str, str] | None:
    """比较两侧对齐的同字段，返回 (kind, compatibility) 或 None（无变化）。"""
    old_s, new_s = old_field.schema, new_field.schema
    struct_changed = sf.structural_signature(old_s) != sf.structural_signature(new_s)
    req_changed = old_required != new_required

    if not struct_changed and not req_changed:
        # 仅可能是注解变化。
        ann_changed = sf._annotation_signature(old_s) != sf._annotation_signature(new_s)
        return (
            {"change_kind": METADATA, "compatibility": METADATA_COMPAT}
            if ann_changed
            else None
        )

    if not struct_changed:
        if new_required:
            return {"change_kind": REQUIRED_ADDED, "compatibility": BREAKING}
        return {"change_kind": REQUIRED_REMOVED, "compatibility": COMPATIBLE}

    verdict = sf.classify_pair(old_s, new_s)
    # 结构变化与必填变化同时发生时，取更严格的结论；种类仍记 modified。
    if new_required and not old_required:
        verdict = BREAKING
    return {"change_kind": MODIFIED, "compatibility": verdict}


def build_report(
    registry: Registry,
    name: str,
    baseline_version: str,
    candidate_document: Any,
    candidate_version: str | None,
    renames: list | None,
) -> dict[str, Any]:
    """构造字段级变更报告（不落盘、不改注册内容）。"""
    old_doc = registry.get_schema(name, baseline_version).document

    old_fields = _expand(old_doc)
    new_fields = _expand(candidate_document)
    old_required = _required_set(old_fields)
    new_required = _required_set(new_fields)

    pairs = validate_renames(renames, old_fields, new_fields)

    # 对齐表：old_path -> new_path（含重命名根子树按后缀对齐）。
    aligned_old: dict[str, str] = {}
    aligned_new: dict[str, str] = {}
    rename_roots: dict[str, str] = dict(pairs)
    for src, dst in pairs:
        src_segs = ptr.parse(src)
        for p in old_fields:
            if p == src or ptr.is_under(src, p):
                suffix = ptr.parse(p)[len(src_segs) :]
                q = ptr.format(ptr.parse(dst) + suffix) if suffix else dst
                if q in new_fields:
                    aligned_old[p] = q
                    aligned_new[q] = p
        # 新侧子树里没有旧侧对应路径的，留给 added 分支。

    changes: list[dict[str, Any]] = []

    def impacts_for(old_path: str) -> dict:
        return analyze_field(registry, name, baseline_version, old_path)

    def add_entry(
        kind: str,
        compat: str,
        old_path: str | None,
        new_path: str | None,
    ) -> None:
        old_s = old_fields[old_path].schema if old_path is not None else None
        new_s = new_fields[new_path].schema if new_path is not None else None
        impacts = impacts_for(old_path) if old_path is not None else None
        changes.append(_entry(kind, compat, old_path, new_path, old_s, new_s, impacts))

    # 1) 重命名根：恰好一条 rename。
    for src, dst in pairs:
        add_entry(RENAMED, BREAKING, src, dst)

    # 2) 旧侧路径。
    for p in sorted(old_fields, key=lambda x: (ptr.parse(x), x)):
        if p in rename_roots:
            continue  # 根已作为 rename 计入
        q = aligned_old.get(p)
        if q is not None:
            # 重命名子树内按后缀对齐的普通字段（跳过根自身）。
            decision = _compare_matched(
                old_fields[p], new_fields[q], p in old_required, q in new_required
            )
            if decision is not None:
                changes.append(
                    _entry(
                        decision["change_kind"],
                        decision["compatibility"],
                        p,
                        q,
                        old_fields[p].schema,
                        new_fields[q].schema,
                        impacts_for(p),
                    )
                )
            continue
        if p in new_fields and not rename_roots:
            # 非重命名场景的公共路径在第 4 步统一处理，避免重复。
            pass
        if p not in aligned_old and _has_unaligned_new(p, new_fields, aligned_new, rename_roots):
            continue
        if p in new_fields:
            continue  # 公共路径交给第 4 步
        add_entry(DELETED, BREAKING, p, None)

    # 3) 新侧路径：新增（含重命名子树中未被旧侧覆盖的部分）。
    for q in sorted(new_fields, key=lambda x: (ptr.parse(x), x)):
        if q in rename_roots.values():
            continue  # rename 终点已计入
        if q in aligned_new:
            continue  # 已在第 2 步对齐处理
        if q in old_fields:
            continue  # 公共路径交给第 4 步
        compat = BREAKING if q in new_required else COMPATIBLE
        add_entry(ADDED, compat, None, q)

    # 4) 非重命名的公共路径。
    for p in sorted(old_fields, key=lambda x: (ptr.parse(x), x)):
        if p in aligned_old or p in rename_roots:
            continue
        if p not in new_fields:
            continue
        decision = _compare_matched(
            old_fields[p], new_fields[p], p in old_required, p in new_required
        )
        if decision is not None:
            changes.append(
                _entry(
                    decision["change_kind"],
                    decision["compatibility"],
                    p,
                    p,
                    old_fields[p].schema,
                    new_fields[p].schema,
                    impacts_for(p),
                )
            )

    if len(changes) > limits.MAX_CHANGES:
        raise ImpactAnalysisTooLarge(
            "变更条目数量超过公开限制",
            details={"reason": "changes_exceeded", "limit": limits.MAX_CHANGES},
        )

    changes.sort(key=lambda e: (ptr.parse(e["path"]), e["path"], e["change_kind"]))

    counts = {BREAKING: 0, COMPATIBLE: 0, METADATA_COMPAT: 0}
    for e in changes:
        counts[e["compatibility"]] += 1

    canonical = json.dumps(
        {
            "schema": name,
            "baseline_version": baseline_version,
            "candidate_version": candidate_version,
            "candidate_document": candidate_document,
            "renames": sorted(pairs),
        },
        sort_keys=True,
        ensure_ascii=False,
        separators=(",", ":"),
    )
    report_id = hashlib.sha256(canonical.encode("utf-8")).hexdigest()[:16]

    return {
        "report_id": report_id,
        "schema": name,
        "baseline_version": baseline_version,
        "candidate_version": candidate_version,
        "renames": [{"from": s, "to": d} for s, d in sorted(pairs)],
        "summary": {
            "total": len(changes),
            "breaking": counts[BREAKING],
            "compatible": counts[COMPATIBLE],
            "metadata": counts[METADATA_COMPAT],
        },
        "changes": changes,
    }


def _has_unaligned_new(p: str, new_fields, aligned_new, rename_roots) -> bool:
    return False

