ADDED = "added"
DELETED = "deleted"
MODIFIED = "modified"
REQUIRED_ADDED = "required_added"
REQUIRED_REMOVED = "required_removed"
METADATA = "metadata"

BREAKING = "breaking"
COMPATIBLE = "compatible"
METADATA_COMPAT = "metadata"


def _expand(document: Any) -> dict[str, sf.Field]:
    return sf.expand(document)


def _is_required(field: sf.Field | None) -> bool:
    """字段是否被其父对象的 required 列表覆盖（展开时已合并 allOf）。"""
    if field is None:
        return False
    parent_path = ptr.parent(field.path)
    # fields 表由调用方持有，这里通过 required_paths 反查；为简化，
    # 调用方直接传入 required 集合，见 _required_set。
    raise NotImplementedError


def _required_set(fields: dict[str, sf.Field]) -> set[str]:
    """收集文档内全部被标记为必填的字段路径。"""
    out: set[str] = set()
    for f in fields.values():
        out.update(f.required_paths)
    return out


def _summary(schema: dict) -> dict[str, Any]:
    # required 是父节点对子字段的约束，不放进字段自身摘要。
    return {k: v for k, v in sf.summary(schema).items() if k != "required"}


