"""全文检索。

索引三类文档：已注册 Schema、目录资产、字段级变更报告中的每条变更。
变更报告生成后自动进入检索范围；新增文档类型不会改变旧查询的结果语义与
排序——排序完全由匹配分与确定性键决定，与索引插入顺序无关。

分词口径：
  * 拉丁字母/数字连续串作为一个词条（小写）；
  * 中日韩字符连续串按二元组切分（单字保留单字）；
  * 所有词条做小写化，匹配采用「查询全部命中」(AND) 语义。
"""

from __future__ import annotations

import re
from dataclasses import dataclass, field

_TOKEN_RE = re.compile(r"[0-9a-z_]+|[一-鿿]+", re.IGNORECASE)


def tokenize(text: str) -> list[str]:
    if text is None:
        return []
    tokens: list[str] = []
    for match in _TOKEN_RE.finditer(str(text).lower()):
        piece = match.group(0)
        if piece and piece[0].isascii() and piece[0].isalnum():
            tokens.append(piece)
        elif piece and piece[0].isdigit():
            tokens.append(piece)
        elif "一" <= piece[0] <= "鿿":
            # CJK 连续串：二元组；长度为 1 时保留单字。
            if len(piece) == 1:
                tokens.append(piece)
            else:
                tokens.extend(piece[i : i + 2] for i in range(len(piece) - 1))
        else:
            tokens.append(piece)
    return tokens


@dataclass
class IndexedDoc:
    doc_type: str  # "schema" | "asset" | "change"
    key: tuple  # 确定性排序键
    fields: dict[str, str]  # 命名字段 -> 原文（用于返回“命中字段”）
    payload: dict  # 不参与匹配的回传内容
    tokens: dict[str, set[str]] = field(default_factory=dict)  # 字段 -> 词条集合


class SearchIndex:
    def __init__(self) -> None:
        self._docs: list[IndexedDoc] = []

    def clear(self) -> None:
        self._docs = []

    def add_doc(self, doc_type: str, key: tuple, fields: dict[str, str], payload: dict) -> None:
        tokens = {name: set(tokenize(value)) for name, value in fields.items() if value}
        self._docs.append(IndexedDoc(doc_type, tuple(key), dict(fields), payload, tokens))

    def search(
        self,
        keyword: str | None = None,
        *,
        doc_type: str | None = None,
        schema: str | None = None,
        version: str | None = None,
        field_path: str | None = None,
        change_kind: str | None = None,
        compatibility: str | None = None,
        asset_name: str | None = None,
        limit: int | None = None,
    ) -> list[dict]:
        """组合检索。所有条件为 AND；keyword 在命名字段上做 AND 全命中。"""
        terms = tokenize(keyword) if keyword else []
        extra_terms = tokenize(asset_name) if asset_name else []

        results: list[tuple[int, tuple, dict]] = []
        for doc in self._docs:
            if doc_type is not None and doc.doc_type != doc_type:
                continue
            p = doc.payload
            if doc.doc_type == "change":
                if schema is not None and p["schema"] != schema:
                    continue
                if version is not None and version not in (
                    p["baseline_version"],
                    p["candidate_version"],
                ):
                    continue
                if field_path is not None and field_path not in (
                    p["path"],
                    p.get("old_path"),
                    p.get("new_path"),
                ):
                    continue
                if change_kind is not None and p["change_kind"] != change_kind:
                    continue
                if compatibility is not None and p["compatibility"] != compatibility:
                    continue
            elif doc.doc_type == "schema":
                if schema is not None and p["name"] != schema:
                    continue
                if version is not None and p["version"] != version:
                    continue
            elif doc.doc_type == "asset":
                if schema is not None and schema not in p["schemas"]:
                    continue
                if version is not None and version not in p["versions"]:
                    continue

            matched_fields = self._match_fields(doc, terms + extra_terms)
            if (terms or extra_terms) and matched_fields is None:
                continue

            # 匹配分：命中的不同字段数（只统计 keyword 词条，过滤条件不计分）。
            score = 0
            if terms:
                hit_fields = {
                    fname
                    for fname, toks in doc.tokens.items()
                    if all(t in toks for t in terms)
                }
                score = len(hit_fields)

            results.append(
                (
                    score,
                    doc.key,
                    {
                        "type": doc.doc_type,
                        "matched_fields": sorted(matched_fields or ()) if (terms or extra_terms) else [],
                        **p,
                    },
                )
            )

        results.sort(key=lambda r: (-r[0], r[1]))
        hits = [r[2] for r in results]
        return hits[:limit] if limit is not None else hits

    @staticmethod
    def _match_fields(doc: IndexedDoc, terms: list[str]) -> set[str] | None:
        if not terms:
            return set()
        matched: set[str] = set()
        for fname, toks in doc.tokens.items():
            if all(t in toks for t in terms):
                matched.add(fname)
        return matched if matched else None

