def normalize_field_pointer(path: str) -> str:
    """把 Schema 文档指针规整为逻辑字段路径。

    与 :func:`meta_catalog.schema_fields.expand` 的展开约定保持一致：
    省略 ``properties`` 关键字段；单 Schema 的 ``items`` 段记为 ``-``。
    例如 ``/properties/a/properties/b`` → ``/a/b``，``/items`` → ``/-``。
    """
    segs = list(parse(path))
    out: list[str] = []
    for i, seg in enumerate(segs):
        if seg in ("properties", "prefixItems"):
            continue
        if seg == "additionalProperties":
            out.append("*")
        elif seg == "items":
            # 元组形式 items/0 展开为数组下标；单 Schema items 展开为 -。
            if i + 1 < len(segs) and segs[i + 1].isdigit():
                continue
            out.append("-")
        else:
            out.append(seg)
    return format(out)

