            key = (asset.id, ref.schema, ref.version, ref.path)
            entry = transitive_map.get(key)
            if entry is None:
                entry = {
                    "asset_id": asset.id,
                    "name": asset.name,
                    "kind": asset.kind,
                    "schema": ref.schema,
                    "version": ref.version,
                    "path": ref.path,
                    "matched_paths": [],
                }
