"""字段级影响分析。

直接影响：资产的字段引用与目标字段 ``(schema, version, path)`` 精确相等。
传递影响：某 Schema 字段通过跨 Schema ``$ref`` 边引用目标字段（或其子树），
资产引用了该 Schema 的对应字段，沿引用边反向逐层传播。

传播时按字段后缀对齐：边 ``S:/a -> T:/p`` 引用了 T 中 ``p`` 子树，则
T 的 ``p/x`` 对应 S 的 ``a/x``。传递结果按稳定标识
``(schema, version, mapped_path)`` 去重。
"""

from __future__ import annotations

from dataclasses import dataclass

from . import limits, pointer as ptr
from .errors import ImpactAnalysisTooLarge
from .registry import Registry, RefEdge


@dataclass(frozen=True)
class Reach:
    schema: str
    version: str
    path: str


def _is_under_or_equal(container: str, path: str) -> bool:
    if container == path:
        return True
    return ptr.is_under(container, path) if container else True


def _join(src_path: str, suffix: tuple[str, ...]) -> str:
    if not suffix:
        return src_path
    return src_path + ptr.format(list(suffix))


def reverse_reach(
    registry: Registry, schema: str, version: str, path: str
) -> list[Reach]:
    """从目标字段反向传播，返回经其他 Schema 到达的全部字段（不含起点）。"""
    # 按目标 Schema 建反向邻接表：dst(schema,version) -> 入边（稳定排序）。
    incoming: dict[tuple[str, str], list[RefEdge]] = {}
    for edge in registry.all_edges():
        incoming.setdefault((edge.dst_schema, edge.dst_version), []).append(edge)
    for edges in incoming.values():
        edges.sort(
            key=lambda e: (
                e.src_schema,
                e.src_version,
                e.src_path,
                e.dst_path,
            )
        )

    reached: dict[Reach, None] = {}
    edges_walked = 0
    # BFS 队列元素：(当前字段, 深度)
    queue: list[tuple[Reach, int]] = [(Reach(schema, version, path), 0)]
    seen_state: set[Reach] = {Reach(schema, version, path)}

    while queue:
        state, depth = queue.pop(0)
        if depth >= limits.MAX_IMPACT_DEPTH:
            raise ImpactAnalysisTooLarge(
                "影响链深度超过公开限制",
                details={
                    "reason": "depth_exceeded",
                    "limit": limits.MAX_IMPACT_DEPTH,
                    "schema": state.schema,
                    "version": state.version,
                    "path": state.path,
                },
            )
        for edge in incoming.get((state.schema, state.version), ()):
            if edge.dst_path == state.path:
                mapped_path = edge.src_path
            elif _is_under_or_equal(edge.dst_path, state.path):
                # 边目标是变更字段祖先：按后缀对齐到源侧字段。
                suffix = ptr.parse(state.path)[len(ptr.parse(edge.dst_path)) :]
                mapped_path = _join(edge.src_path, suffix)
            elif ptr.is_under(state.path, edge.dst_path):
                # 变更字段是边目标祖先：源侧被引用子树整体受影响，
                # 到达点取源侧边的源路径（子树根）。
                mapped_path = edge.src_path
            else:
                continue
            edges_walked += 1
            if edges_walked > limits.MAX_IMPACT_VISITED:
                raise ImpactAnalysisTooLarge(
                    "影响链引用边数量超过公开限制",
                    details={"reason": "edges_exceeded", "limit": limits.MAX_IMPACT_VISITED},
                )
            mapped = Reach(edge.src_schema, edge.src_version, mapped_path)
            if mapped in seen_state:
                continue
            seen_state.add(mapped)
            reached[mapped] = None
            queue.append((mapped, depth + 1))

    return sorted(reached.keys(), key=lambda r: (r.schema, r.version, r.path))


def analyze_field(registry: Registry, schema: str, version: str, path: str) -> dict:
    """返回单个字段的影响资产：直接 + 传递（各自稳定排序、去重）。"""
    # 触发不存在的版本错误，保持错误码语义。
    registry.get_schema(schema, version)

    direct: dict[str, dict] = {}
    for asset in registry.all_assets():
        for ref in asset.refs:
            if ref.schema == schema and ref.version == version and ref.path == path:
                direct[asset.id] = {
                    "asset_id": asset.id,
                    "name": asset.name,
                    "kind": asset.kind,
                }
                break

    transitive_map: dict[tuple[str, str, str, str], dict] = {}
    for reach in reverse_reach(registry, schema, version, path):
        for asset in registry.all_assets():
            for ref in asset.refs:
                if ref.schema != reach.schema or ref.version != reach.version:
                    continue
                # 资产引用与传递到达点相同，或互为包含（整对象包含变更字段、
                # 或引用点位于变更字段子树内）都视为传递命中。
                if not (
                    ref.path == reach.path
                    or ptr.is_under(ref.path, reach.path)
                    or ptr.is_under(reach.path, ref.path)
                ):
                    continue
                key = (asset.id, reach.schema, reach.version, ref.path)
                entry = transitive_map.get(key)
                if entry is None:
                    entry = {
                        "asset_id": asset.id,
                        "name": asset.name,
                        "kind": asset.kind,
                        "schema": reach.schema,
                        "version": reach.version,
                        "path": ref.path,
                        "matched_paths": [],
                    }
                    transitive_map[key] = entry
                if reach.path not in entry["matched_paths"]:
                    entry["matched_paths"].append(reach.path)

    transitive = list(transitive_map.values())
    for entry in transitive:
        entry["matched_paths"].sort(key=lambda p: (ptr.parse(p), p))

    if len(direct) + len(transitive) > limits.MAX_IMPACT_ASSETS:
        raise ImpactAnalysisTooLarge(
            "影响资产数量超过公开限制",
            details={"reason": "assets_exceeded", "limit": limits.MAX_IMPACT_ASSETS},
        )

    return {
        "schema": schema,
        "version": version,
        "path": path,
        "direct_assets": [direct[k] for k in sorted(direct)],
        "transitive_assets": sorted(
            transitive,
            key=lambda a: (a["asset_id"], a["schema"], a["version"], a["path"]),
        ),
    }

